        private void ClearCacheView(ControllerContext controllerContext)
        {
            var CustomQueryString = controllerContext.RequestContext.HttpContext.Request.QueryString["custom"];
            if (CustomQueryString != null)
            {
                if (CustomQueryString.Equals("off", StringComparison.InvariantCultureIgnoreCase))
                {
                    IEnumerator en = controllerContext.HttpContext.Cache.GetEnumerator();

                    while (en.MoveNext())
                    {
                        DictionaryEntry item = (DictionaryEntry)en.Current;
                        controllerContext.HttpContext.Cache.Remove(item.Key.ToString());
                    }
                }
            }
        }
